CREATE TABLE "Country" ("iso" TEXT NOT NULL PRIMARY KEY,"nameRu" TEXT NOT NULL,"nameEn" TEXT NOT NULL,"lat" REAL NOT NULL,"lng" REAL NOT NULL,"wave" INTEGER NOT NULL,"primaryLang" TEXT NOT NULL);
CREATE TABLE "CountryDirectionMonthly" ("iso" TEXT NOT NULL,"direction" TEXT NOT NULL,"monthIndex" INTEGER NOT NULL,"primaryMetric" INTEGER NOT NULL,"secondaryMetric" INTEGER NOT NULL,"capture" REAL NOT NULL,PRIMARY KEY("iso","direction","monthIndex"));
CREATE TABLE "GlobalMonthly" ("monthIndex" INTEGER NOT NULL PRIMARY KEY,"users" INTEGER NOT NULL,"publishedProjects" INTEGER NOT NULL,"schools" INTEGER NOT NULL,"ambassadors" INTEGER NOT NULL,"activeCampaigns" INTEGER NOT NULL);
CREATE TABLE "Feedback" ("id" TEXT NOT NULL PRIMARY KEY,"iso" TEXT NOT NULL,"direction" TEXT NOT NULL,"authorType" TEXT NOT NULL,"nickname" TEXT NOT NULL,"category" TEXT NOT NULL,"lang" TEXT NOT NULL,"textOriginal" TEXT NOT NULL,"textRu" TEXT NOT NULL,"textEn" TEXT NOT NULL,"sentiment" TEXT NOT NULL,"votes" INTEGER NOT NULL,"status" TEXT NOT NULL,"createdAt" DATETIME NOT NULL);
